from torch.utils.data import Dataset, DataLoader

class CharSeq2SeqDataset(Dataset):
    def __init__(self, pairs, input_vocab, output_vocab, max_len=10):
        self.pairs = pairs
        self.input_vocab = input_vocab
        self.output_vocab = output_vocab
        self.max_len = max_len

    def __len__(self):
        return len(self.pairs)

    def __getitem__(self, idx):
        eng, fra = self.pairs[idx]
        # Convert to indices; assume <sos> = 0, <eos> = 1, <pad> = 2
        src = [self.input_vocab.get(c, 2) for c in eng][:self.max_len] + [1]
        tgt = [0] + [self.output_vocab.get(c, 2) for c in fra][:self.max_len] + [1]
        return torch.tensor(src), torch.tensor(tgt)

